/**
 * Namespace global pour eviter de polluer window.
 * Les fonctions sont exposees ici d'abord, puis sur window uniquement
 * quand elles sont necessaires pour les onclick inline du HTML.
 * Migration progressive : remplacer window.xxx par POKETIME.xxx dans le JS,
 * puis supprimer les exports window.xxx quand les onclick inline seront remplaces.
 */
const POKETIME: Record<string, unknown> = (typeof window !== 'undefined' && window.POKETIME) || {};
if (typeof window !== 'undefined') {
    window.POKETIME = POKETIME;
}

export function debugLog(...args: unknown[]): void {
    devLog(...args);
}

export function debugWarn(...args: unknown[]): void {
    devWarn(...args);
}

export function debugError(...args: unknown[]): void {
    devError(...args);
}

/**
 * Formate un nombre avec des suffixes (K, M, B)
 * Affichage global (2 décimales, ex: 9.84M)
 */
export function formatNumber(num: number | string | null | undefined): string {
    const n = Number(num);
    if (!Number.isFinite(n)) {
        return '0';
    }

    const sign = n < 0 ? '-' : '';
    const abs = Math.abs(n);

    if (abs >= 1e3) {
        const suffixes = ['', 'K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp', 'Oc', 'No', 'Dc'];
        const tier = Math.floor(Math.log10(abs) / 3);
        if (tier < suffixes.length) {
            const scaled = abs / Math.pow(1000, tier);
            return sign + scaled.toFixed(2) + suffixes[tier];
        }
        return sign + abs.toExponential(2);
    }

    return sign + Math.floor(abs).toString();
}

/**
 * Formate un nombre avec plus de précision pour le header
 * (alias de formatNumber pour garder la compatibilité)
 */
export function formatNumberHeader(num: number | string | null | undefined): string {
    return formatNumber(num);
}

interface TimeFormat {
    hours: number;
    minutes: number;
    seconds: number;
}

// Reusable object to avoid allocations in game loops
const _timeFormatObj: TimeFormat = { hours: 0, minutes: 0, seconds: 0 };

/**
 * Formate une durée en millisecondes
 * Mutates and returns a shared object to avoid GC pressure
 */
export function formatTime(milliseconds: number): TimeFormat {
    _timeFormatObj.hours = Math.floor(milliseconds / 3600000);
    _timeFormatObj.minutes = Math.floor((milliseconds % 3600000) / 60000);
    _timeFormatObj.seconds = Math.floor((milliseconds % 60000) / 1000);

    return _timeFormatObj;
}

/** Durées >= 100 h affichées en jours + heures (ex. 6d 6h). */
const DAY_HOUR_FORMAT_THRESHOLD_HOURS = 100;

/** Boosts / timers : au-delà de 1 h, utiliser h/m/s ou d/h au lieu de milliers de minutes. */
const BOOST_USE_HMS_THRESHOLD_MS = 60 * 60 * 1000;

export interface BoostTimeLeftLabels {
    minuteShort: string;
    secondShort: string;
}

/**
 * Durée restante d'un boost temporaire (tooltip header).
 * Sous 1 h : min/s localisés ; à partir de 1 h : même logique que formatTimeString (d/h si >= 100 h).
 */
export function formatBoostTimeLeft(milliseconds: number, labels: BoostTimeLeftLabels): string {
    const ms = Math.max(0, milliseconds);
    if (ms >= BOOST_USE_HMS_THRESHOLD_MS) {
        return formatTimeString(ms);
    }
    const min = Math.floor(ms / 60000);
    const sec = Math.floor((ms % 60000) / 1000);
    return `${min} ${labels.minuteShort} ${sec.toString().padStart(2, '0')} ${labels.secondShort}`;
}

/**
 * Formate une durée en chaîne lisible
 */
export function formatTimeString(milliseconds: number): string {
    const totalHours = Math.floor(milliseconds / 3600000);
    if (totalHours >= DAY_HOUR_FORMAT_THRESHOLD_HOURS) {
        const days = Math.floor(totalHours / 24);
        const hours = totalHours % 24;
        return `${days}d ${hours}h`;
    }
    const m = Math.floor((milliseconds % 3600000) / 60000);
    const s = Math.floor((milliseconds % 60000) / 1000);
    return `${totalHours}h ${m}m ${s}s`;
}

const _relativeTimeFormatters = new Map<string, Intl.RelativeTimeFormat>();

function getRelativeTimeFormatter(lang: 'fr' | 'en'): Intl.RelativeTimeFormat {
    const locale = lang === 'en' ? 'en-US' : 'fr-FR';
    let rtf = _relativeTimeFormatters.get(locale);
    if (!rtf) {
        rtf = new Intl.RelativeTimeFormat(locale, { numeric: 'auto' });
        _relativeTimeFormatters.set(locale, rtf);
    }
    return rtf;
}

/**
 * Durée écoulée en texte relatif localisé (ex. « il y a 25 secondes », « 25 seconds ago »).
 */
export function formatRelativeTimeAgo(msAgo: number, lang: 'fr' | 'en'): string {
    const ms = Math.max(0, msAgo);
    const rtf = getRelativeTimeFormatter(lang);
    const seconds = Math.floor(ms / 1000);
    if (seconds < 60) return rtf.format(-seconds, 'second');
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return rtf.format(-minutes, 'minute');
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return rtf.format(-hours, 'hour');
    const days = Math.floor(hours / 24);
    return rtf.format(-days, 'day');
}

/**
 * Formate un pourcentage
 */
export function formatPercentage(value: number, decimals = 1): string {
    return (value * 100).toFixed(decimals) + '%';
}

const _floatingNumberFormatter = new Intl.NumberFormat('fr-FR');

/**
 * Formate les nombres pour l'affichage des dégâts flottants
 * (avec des espaces, ex: "1 234 567")
 */
export function formatFloatingNumber(num: number | null | undefined): string {
    if (num == null || isNaN(num)) {
        return '0';
    }
    return _floatingNumberFormatter.format(Math.floor(num));
}

/**
 * Formate les nombres des floating texts de combat selon l'option joueur
 * damagePopupCompactNumbers (entier vs abrégé K/M/B).
 */
export function formatCombatFloatingNumber(
    game: GameRuntime | null | undefined,
    num: number | null | undefined,
): string {
    if (game?.damagePopupCompactNumbers) return formatNumber(num);
    return formatFloatingNumber(num);
}

const _escapeMap: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const _escapeRe = /[&<>"']/g;

/**
 * Echappe les caractères HTML dangereux dans une chaîne.
 * A utiliser systématiquement avant toute injection via innerHTML.
 */
export function escapeHtml(str: unknown): string {
    if (typeof str !== 'string') return typeof str === 'number' || typeof str === 'boolean' ? String(str) : '';
    return str.replace(_escapeRe, ch => _escapeMap[ch] ?? ch);
}

/**
 * Prépare les variables pour un modèle i18n : noms de Pokémon selon la langue du jeu,
 * échappement HTML — même logique que {@link Game.prototype.t}.
 */
export function localizeTemplateSubstitutionVars(game: GameRuntime | null | undefined, vars: Record<string, unknown> = {}): Record<string, unknown> {
    const inputVars = vars && typeof vars === 'object' ? vars : {};
    if (!game || typeof game.normalizeLanguage !== 'function') {
        return inputVars;
    }
    const lang: string = game.normalizeLanguage(game.language);
    const localizedVars: Record<string, unknown> = {};
    for (const [varKey, varValue] of Object.entries(inputVars)) {
        if (typeof varValue === 'string') {
            let s: string = String(varValue);
            const localize = typeof globalThis.localizePokemonName === 'function'
                ? globalThis.localizePokemonName
                : undefined;
            if (typeof localize === 'function') {
                s = localize(s, lang);
            }
            localizedVars[varKey] = escapeHtml(s);
        } else {
            localizedVars[varKey] = varValue;
        }
    }
    return localizedVars;
}


/**
 * Génère une clé de shard (basée sur la famille uniquement)
 */
export function getShardKey(creatureName: string, _rarity: unknown): string {
    const canonicalName = resolveCanonicalSpeciesName(creatureName);
    const familyName = (EVOLUTION_FAMILIES as Record<string, string>)[canonicalName] || canonicalName;
    return familyName;
}

/**
 * Trouve l’ancêtre vertical scrollable le plus proche d’une liste (pour IntersectionObserver.root).
 * Évite le décalage quand le scroll réel se fait sur `.tab-content` ou un parent interne
 * plutôt que sur `.secondary-content` / `.team-area`.
 * @param listElement - Conteneur de la grille (ex. `#pokedexList`).
 * @param fallbackSelectors - Sélecteurs ou nœuds essayés si aucun ascendant scrollable.
 * @returns null = viewport (root par défaut de l'API).
 */
export function getLazyListScrollRoot(listElement: Element | null, fallbackSelectors?: (string | Element)[] | string | Element): Element | null {
    if (!listElement || typeof (listElement as HTMLElement).parentElement === 'undefined') return null;
    let el: HTMLElement | null = (listElement as HTMLElement).parentElement;
    while (el && el !== document.documentElement) {
        const style = window.getComputedStyle(el);
        const oy = style.overflowY;
        const overflow = style.overflow;
        if (oy === 'auto' || oy === 'scroll' || oy === 'overlay') {
            return el;
        }
        if (overflow === 'auto' || overflow === 'scroll') {
            return el;
        }
        el = el.parentElement;
    }
    const fallbacks: (string | Element)[] = Array.isArray(fallbackSelectors) ? fallbackSelectors : (fallbackSelectors ? [fallbackSelectors] : []);
    for (let i = 0; i < fallbacks.length; i++) {
        const sel = fallbacks[i];
        const node = typeof sel === 'string' ? document.querySelector(sel) : sel;
        if (node) return node;
    }
    return null;
}

/** Prestige star glyph (plain text tooltips / titles). */
export const PRESTIGE_STAR = '\u2B50';

export const SHINY_BADGE_URL = 'img/shiny-logo.png';
export const PRESTIGE_STAR_IMG_URL = 'img/prestige-star.png';

/** In-game prestige suffix, e.g. prestige 3 → "3⭐". Empty when prestige is 0. */
export function formatPrestigeSuffix(prestige: number): string {
    const p = Math.floor(Number(prestige) || 0);
    return p > 0 ? `${p}${PRESTIGE_STAR}` : '';
}

/** Same as formatPrestigeSuffix with a leading space for name suffixes. */
export function formatPrestigeSuffixSpaced(prestige: number): string {
    const suffix = formatPrestigeSuffix(prestige);
    return suffix ? ` ${suffix}` : '';
}

/** Single shiny badge sprite for HTML UIs. */
export function shinyBadgeHtml(title = 'Shiny', className = 'shiny-badge-icon'): string {
    const safeTitle = escapeHtml(title);
    return `<img src="${SHINY_BADGE_URL}" class="${className}" alt="" title="${safeTitle}" aria-hidden="true">`;
}

/** Prestige suffix with sprite star, e.g. prestige 3 → badge "3" + star img. */
export function formatPrestigeSuffixHtml(prestige: number): string {
    const p = Math.floor(Number(prestige) || 0);
    if (p <= 0) return '';
    return `<span class="prestige-badge">${p}<img src="${PRESTIGE_STAR_IMG_URL}" class="prestige-star-icon" alt="" aria-hidden="true"></span>`;
}

/** Same as formatPrestigeSuffixHtml with a leading space. */
export function formatPrestigeSuffixSpacedHtml(prestige: number): string {
    const suffix = formatPrestigeSuffixHtml(prestige);
    return suffix ? ` ${suffix}` : '';
}

