POKETIME.formatPercentage = formatPercentage;
POKETIME.formatFloatingNumber = formatFloatingNumber;
POKETIME.getShardKey = getShardKey;
POKETIME.escapeHtml = escapeHtml;
POKETIME.localizeTemplateSubstitutionVars = localizeTemplateSubstitutionVars;
POKETIME.debugLog = debugLog;
POKETIME.debugWarn = debugWarn;
POKETIME.debugError = debugError;
POKETIME.getLazyListScrollRoot = getLazyListScrollRoot;
