/**
 * Encounter / PokeAPI ASCII names → canonical roster keys (dex, pool, evolutions).
 */

export const ROSTER_SPECIES_ALIASES: Readonly<Record<string, string>> = {
    Flabebe: 'Flabébé',
};

export function resolveCanonicalSpeciesName(name: string): string {
    const raw = String(name || '').trim();
    if (!raw) return raw;
    return ROSTER_SPECIES_ALIASES[raw] ?? raw;
}

/** Zone pool name → canonical tier key (merges alias + canonical progress). */
export function getZonePokemonTier(
    tiers: Record<string, number> | undefined,
    speciesName: string,
): number {
    if (!tiers) return 0;
    const canonical = resolveCanonicalSpeciesName(speciesName);
    const canonicalTier = Number(tiers[canonical]) || 0;
    if (speciesName === canonical) return canonicalTier;
    const aliasTier = Number(tiers[speciesName]) || 0;
    return Math.max(canonicalTier, aliasTier);
}

/** Increment zone tier under the canonical species key; fold alias keys into canonical. */
export function incrementZonePokemonTier(
    tiers: Record<string, number>,
    speciesName: string,
    maxTier: number,
): void {
    const canonical = resolveCanonicalSpeciesName(speciesName);
    const current = getZonePokemonTier(tiers, speciesName);
    if (current >= maxTier) return;
    tiers[canonical] = current + 1;
    if (canonical !== speciesName) delete tiers[speciesName];
    for (const alias of Object.keys(ROSTER_SPECIES_ALIASES)) {
        if (ROSTER_SPECIES_ALIASES[alias] === canonical) delete tiers[alias];
    }
}

export function normalizeZonePokemonTiersMap(tiers: Record<string, number>): void {
    for (const [alias, canonical] of Object.entries(ROSTER_SPECIES_ALIASES)) {
        mergeZonePokemonTiers(tiers, alias, canonical);
    }
}

function mergeShardCounts(
    shards: Record<string, number>,
    alias: string,
    canonical: string,
): void {
    const aliasCount = Math.max(0, Number(shards[alias]) || 0);
    if (aliasCount <= 0) return;
    shards[canonical] = (Math.max(0, Number(shards[canonical]) || 0)) + aliasCount;
    delete shards[alias];
}

function mergeZonePokemonTiers(
    tiers: Record<string, number>,
    alias: string,
    canonical: string,
): void {
    const aliasTier = Number(tiers[alias]);
    if (!Number.isFinite(aliasTier) || aliasTier <= 0) return;
    const canonicalTier = Number(tiers[canonical]) || 0;
    tiers[canonical] = Math.max(canonicalTier, aliasTier);
    delete tiers[alias];
}

/** Merge encounter alias keys (shards, zone tiers, protected shards) after species rename. */
export function migrateEncounterSpeciesAliasesInSaveData(gameData: {
    shards?: Record<string, number>;
    protectedShards?: string[];
    zoneProgress?: Record<string, { pokemonTiers?: Record<string, number> }>;
}): void {
    for (const [alias, canonical] of Object.entries(ROSTER_SPECIES_ALIASES)) {
        if (gameData.shards && typeof gameData.shards === 'object') {
            mergeShardCounts(gameData.shards, alias, canonical);
        }

        if (Array.isArray(gameData.protectedShards)) {
            gameData.protectedShards = gameData.protectedShards.map((key) =>
                key === alias ? canonical : key,
            );
        }

        if (!gameData.zoneProgress || typeof gameData.zoneProgress !== 'object') continue;
        for (const progress of Object.values(gameData.zoneProgress)) {
            if (!progress?.pokemonTiers || typeof progress.pokemonTiers !== 'object') continue;
            mergeZonePokemonTiers(progress.pokemonTiers, alias, canonical);
        }
    }
}
