/**
 * Opt-in debug logging (localStorage poketime:debug=1).
 * Silent by default in dev and prod — production-ready console.
 */

export const DEBUG_STORAGE_KEY = 'poketime:debug';

export function isVerboseDebugEnabled(): boolean {
  if (typeof localStorage === 'undefined') return false;
  try {
    return localStorage.getItem(DEBUG_STORAGE_KEY) === '1';
  } catch {
    return false;
  }
}

type ConsoleLevel = 'log' | 'warn' | 'error' | 'info' | 'debug';

/** Indirect console access so prod minifiers do not strip opt-in debug output. */
export function writeConsole(level: ConsoleLevel, args: unknown[]): void {
  const c = (globalThis as unknown as { console?: Partial<Record<ConsoleLevel, (...a: unknown[]) => void>> }).console;
  const fn = c?.[level];
  if (typeof fn === 'function') fn(...args);
}

function gated(level: ConsoleLevel, args: unknown[]): void {
  if (!isVerboseDebugEnabled()) return;
  writeConsole(level, args);
}

/** Bootstrap / migration traces */
export function devLog(...args: unknown[]): void {
  gated('log', args);
}

export function devWarn(...args: unknown[]): void {
  gated('warn', args);
}

export function devError(...args: unknown[]): void {
  gated('error', args);
}

export function devTable(data: unknown, columns?: string[]): void {
  if (!isVerboseDebugEnabled()) return;
  const t = (globalThis as { console?: { table?: (d: unknown, c?: string[]) => void } }).console?.table;
  if (typeof t === 'function') t(data, columns);
}
